                duration: te.duration,
                billable: te.billable,
                workspace_id: te.workspace_id,
                tags: te.tags.unwrap_or_default(),
                project: None,
                task: None,
            Box::new(ApiError::NetworkWithMessage(format!(
                "{e}; response body: {response_body}"
            ))) as Box<dyn std::error::Error + Send>
        })
    }

    async fn get_weekly_report(
        &self,
        workspace_id: i64,
        body: Value,
    ) -> ResultWithDefaultError<Value> {
        let url = format!(
            "{}/workspace/{}/weekly/time_entries",
            self.reports_base_url(),
            workspace_id
        );
        let response_body = self
            .send_raw(self.http_client.post(&url).json(&body), &url)
            .await?;
        serde_json::from_str(&response_body).map_err(|e| {
            Box::new(ApiError::NetworkWithMessage(format!(
                "{e}; response body: {response_body}"
            ))) as Box<dyn std::error::Error + Send>
        })
    }

    async fn get_entities(&self) -> ResultWithDefaultError<Entities> {
        let (
            network_time_entries,
            network_projects,
            network_tasks,
            network_clients,
            network_workspaces,
        ) = tokio::join!(
            self.get_time_entries(None, None),
            self.get_projects(),
            self.get_tasks(),
            self.get_clients(),
            self.get_workspaces(),
        );

        let clients: HashMap<i64, crate::models::Client> = network_clients
            .unwrap_or_default()
            .iter()
            .map(|c| {
                (
                    c.id,
                    crate::models::Client {
                        id: c.id,
                        name: c.name.clone(),
                        workspace_id: c.wid,

                // id is guaranteed Some due to validation above
                ShowCommand::execute(api_client, id.unwrap(), json).await
            }
        }
        EntryAction::Update {
            id,
            current,
            description,
            billable,
            project,
            task,
            tags,
            start,
            end,
            json,
        } => {
            if current {
                // Check if there's a running entry before attempting edit
                match api_client.get_current_time_entry_minimal().await? {
                    Some(_) => {
                        // There's a running entry, let EditCommand handle it with id=None
                        EditCommand::execute(
                            api_client,
                            None,
                            description,
                            billable,
                            project,
                            task,
                            tags,
                            start,
                            end,
                            json,
                        )
                        .await
                    }
                    None => Err(Box::new(error::ArgumentError::ResourceNotFound(
                        "no time entry is currently running".to_string(),
                    ))),
                }
            } else {
                EditCommand::execute(
                    api_client,
                    id,
                    description,
                    billable,
                    project,
                    task,
                    tags,
                    start,
                    end,
                    json,
                )
                .await
            }
        }
        EntryAction::Delete { id, current, json } => {
            if current {
                // Get the current running entry and delete it
                match api_client.get_current_time_entry_minimal().await? {
                    Some(entry) => DeleteCommand::execute(api_client, entry.id, json).await,
                    None => Err(Box::new(error::ArgumentError::ResourceNotFound(
                        "no time entry is currently running".to_string(),
                    ))),
                }
            } else {
                // id is guaranteed Some due to validation above
                DeleteCommand::execute(api_client, id.unwrap(), json).await
            }
        }
        EntryAction::Search {
            query,
            project,
            no_project,
            tags,
            no_tag,
            since,
            until,
            number,
            order_by,
            order_dir,
            json,
        } => {
            commands::search::execute(
                api_client, query, project, no_project, tags, no_tag, since, until, number,
                order_by, order_dir, json,
            )
            .await
        }
        EntryAction::BulkEdit { ids, json } => {
            // json is guaranteed Some due to validation above
            BulkEditTimeEntriesCommand::execute(api_client, ids.clone(), json.clone().unwrap())
                .await
        }
    }
}

